Hi, I have the same use case but it's using RS256 for the encryption. For the RSA I'm using [jsencrypt](https://github.com/travist/jsencrypt) and for the hashing using [k6/crypto](https://k6.io/docs/javascript-api/k6-crypto/) and it's working.

```javascript
import crypto from 'k6/crypto';
import { sleep } from 'k6';
import { JSEncrypt } from './jsencrypt.js'

const secretFile = open("./artifacts/secrets/secret.key");

let encrypt = (secret, data) => {
  let sign = new JSEncrypt();
  sign.setPrivateKey(secret);
  
  return sign.sign(data, (d) => {
      return crypto.sha256(d, 'hex');
  }, "sha256");
};

export function setup() {
  let payload = {
    "username": "your-username",
    "password": "your-password"
  };

  let token = encrypt(secretFile, JSON.stringify(payload));
  return {
    payload: payload,
    token: token
  }
}

export default function(data) {
  // console.log("payload", data.payload);
  console.log("token", data.token);
  sleep(1);
}
```
